func (s *Store) subscriberLoop(sub *subscriber) {
    s.mu.Lock()
    defer func() {
        delete(s.subscribers, sub)
        close(sub.ch)
        close(sub.errors)
        s.mu.Unlock()
        close(sub.stopped)
